package org.humanjourney.core.mapfeature;
import java.util.*;
import com.google.gson.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.humanjourney.core.geography.*;
import org.humanjourney.core.water.WaterGeography.Point;
import org.humanjourney.core.mapfeature.client.*;
class GeometryV2Test {
 static final String OUTER="[[0,0],[200,0],[200,200],[0,200]]",HOLE="[[50,50],[100,50],[100,100],[50,100]]";
 static String polygon(String id,String outer,String holes,int priority){return json(id,2,"{\"type\":\"polygon\",\"outer\":"+outer+",\"holes\":"+holes+"}",priority);}
 static String json(String id,int schema,String geometry,int priority){var o=JsonParser.parseString(FeatureModelTest.polygon(id,priority)).getAsJsonObject();o.addProperty("schema_version",schema);o.add("geometry",JsonParser.parseString(geometry));return o.toString();}
 static String multipart(String id){return json(id,2,"{\"type\":\"multipolygon\",\"polygons\":[{\"outer\":[[-200,0],[-100,0],[-100,200],[-200,200]]},{\"outer\":"+OUTER+",\"holes\":["+HOLE+"]}]}",1);}
 static MapFeature feature(String s){return FeatureModelTest.parse(s);}
 static FeatureGeometry.Ring circle(int count,double x,double z,double radius){var points=new ArrayList<Point>();for(int i=0;i<count;i++){double a=i*2*Math.PI/count;points.add(new Point(x+radius*Math.cos(a),z+radius*Math.sin(a)));}return new FeatureGeometry.Ring(points);}
 static FeatureGeometry large(){var parts=new ArrayList<FeatureGeometry.Part>();for(int i=0;i<128;i++)parts.add(new FeatureGeometry.Part(circle(32,i*100,0,10),List.of()));return FeatureGeometry.multipolygon(parts);}
 static MapFeature.View view(String id,FeatureGeometry geometry){return new MapFeature.View(id,"Label "+id,MapFeature.Type.SEA,FeatureModelTest.DIM,1,geometry);}
 @AfterEach void reset(){FeatureCatalog.reset();}
 @Test void v1PolygonAndV2WithoutHolesHaveIdenticalGeometry(){var old=feature(FeatureModelTest.polygon("sea",1));var next=feature(polygon("sea","[[0,0],[100,0],[100,100],[0,100]]","[]",1));assertEquals(1,old.schemaVersion());assertEquals(2,next.schemaVersion());assertEquals(old.view().geometry(),next.view().geometry());for(int x=-1;x<=101;x++)assertEquals(old.view().geometry().contains(x,50),next.view().geometry().contains(x,50));}
 @Test void holeExcludesInteriorAndAllBoundaryEdgesButOuterBoundaryRemainsInclusive(){var g=feature(polygon("sea",OUTER,"["+HOLE+"]",1)).view().geometry();assertTrue(g.contains(20,20));assertFalse(g.contains(75,75));for(var p:List.of(new Point(50,50),new Point(75,50),new Point(100,75),new Point(75,100),new Point(50,75)))assertFalse(g.contains(p.x(),p.z()));assertTrue(g.contains(0,100));assertFalse(g.contains(201,100));}
 @Test void waterInteriorDiscoversAndDeepHoleDoesNot(){var data=FeatureModelTest.catalog(polygon("sea",OUTER,"["+HOLE+"]",1));var role=new GeographyRoles(true,true,false);var deep=new FeatureDiscovery();assertTrue(deep.discover(role,data,FeatureModelTest.DIM,75,75).isEmpty());var water=new FeatureDiscovery();assertEquals(Set.of("sea"),water.discover(role,data,FeatureModelTest.DIM,25,25));}
 @Test void holeCoastAndOuterCoastProximityDiscoverFromLand(){var data=FeatureModelTest.catalog(polygon("sea",OUTER,"["+HOLE+"]",1));var role=new GeographyRoles(true,true,false);for(var p:List.of(new Point(50,75),new Point(58,75),new Point(-8,100))){var d=new FeatureDiscovery();assertEquals(Set.of("sea"),d.discover(role,data,FeatureModelTest.DIM,p.x(),p.z()));}assertTrue(new FeatureDiscovery().discover(role,data,FeatureModelTest.DIM,58.01,75).isEmpty());}
 @Test void multipartContainmentUsesAnyPartWithItsOwnHoles(){var g=feature(multipart("multi")).view().geometry();assertEquals(FeatureGeometry.Kind.MULTIPOLYGON,g.kind());assertTrue(g.contains(-150,50));assertTrue(g.contains(150,150));assertFalse(g.contains(-50,50));assertFalse(g.contains(75,75));assertFalse(g.contains(50,75));assertEquals(2,g.parts().size());assertEquals(1,g.holeCount());}
 @Test void eitherComponentDiscoversOneStableIdentityAndReentryDoesNotNotifyAgain(){var data=FeatureModelTest.catalog(multipart("multi"));for(double x:List.of(-150D,150D)){var d=new FeatureDiscovery();assertEquals(Set.of("multi"),d.discover(new GeographyRoles(true,true,false),data,FeatureModelTest.DIM,x,150));assertEquals(1,d.snapshot().ids().size());assertEquals(1,d.snapshot().revision());assertTrue(d.discover(new GeographyRoles(true,true,false),data,FeatureModelTest.DIM,-150,50).isEmpty());}}
 @Test void discoveredStableIdSurvivesDefinitionMigrationAndCatalogMixesVersions(){var ledger=new FeatureDiscovery();ledger.mark("sea");FeatureCatalog.accept(FeatureModelTest.catalog(FeatureModelTest.polygon("sea",1)));long revision=ledger.snapshot().revision();FeatureCatalog.accept(FeatureModelTest.catalog(polygon("sea",OUTER,"["+HOLE+"]",1),FeatureModelTest.line("old_river",2)));var projected=FeatureCatalog.project(FeatureCatalog.state().data(),ledger.snapshot().ids());assertEquals(Set.of("sea"),projected.keySet());assertFalse(projected.get("sea").geometry().contains(75,75));assertEquals(revision,ledger.snapshot().revision());}
 @Test void priorityStillSelectsStraitSeaThenOceanAndHolesAreNotPriorityMasks(){var ocean=polygon("ocean","[[0,0],[400,0],[400,400],[0,400]]","["+HOLE+"]",10);var sea=polygon("sea","[[0,0],[300,0],[300,300],[0,300]]","["+HOLE+"]",20);var strait=polygon("strait",OUTER,"["+HOLE+"]",30);var index=FeatureModelTest.catalog(ocean,sea,strait).index();assertEquals("strait",index.hover(FeatureModelTest.DIM,150,150,5).feature().id());assertEquals("sea",index.hover(FeatureModelTest.DIM,250,250,5).feature().id());assertEquals("ocean",index.hover(FeatureModelTest.DIM,350,350,5).feature().id());assertNull(index.hover(FeatureModelTest.DIM,75,75,5).feature());}
 @Test void tiesStillFailClosedAndDirectRiverStillWins(){var water=polygon("sea",OUTER,"["+HOLE+"]",100);var river=FeatureModelTest.line("river",-100);var index=FeatureModelTest.catalog(water,river).index();assertEquals("river",index.hover(FeatureModelTest.DIM,25,50,5).feature().id());var tied=FeatureModelTest.catalog(water,polygon("other",OUTER,"["+HOLE+"]",100)).index().hover(FeatureModelTest.DIM,150,150,5);assertTrue(tied.ambiguous());assertNull(tied.feature());}
 @Test void v2PolylineRemainsOpenWithSameToleranceAndDiscovery(){var old=FeatureModelTest.line("river",1);var o=JsonParser.parseString(old).getAsJsonObject();o.addProperty("schema_version",2);var next=feature(o.toString());assertEquals(feature(old).view().geometry(),next.view().geometry());assertTrue(next.view().geometry().near(50,58,8));assertFalse(next.view().geometry().near(50,58.01,8));assertEquals(1,next.view().geometry().segments());}
 @Test void componentIndexDoesNotReturnFeatureBetweenDistantParts(){var data=FeatureModelTest.catalog(multipart("multi"));assertTrue(data.index().queryParts(FeatureModelTest.DIM,FeatureIndex.around(-50,50,1)).isEmpty());assertEquals(1,data.index().queryParts(FeatureModelTest.DIM,FeatureIndex.around(-150,50,1)).size());assertNull(data.index().hover("minecraft:the_nether",150,150,5).feature());assertTrue(new FeatureDiscovery().discover(new GeographyRoles(true,true,false),data,FeatureModelTest.DIM,-50,50).isEmpty());}
 @Test void selectedComponentAndViewportCullingKeepSingleFeatureIdentity(){var f=feature(multipart("multi")).view();var index=new FeatureIndex(List.of(f));var first=index.hover(f.dimension(),-150,50,5);var second=index.hover(f.dimension(),150,150,5);assertEquals(f,first.feature());assertEquals(f,second.feature());assertEquals(0,first.partIndex());assertEquals(1,second.partIndex());var visible=FeaturePresentation.persistentParts(index,f.dimension(),FeatureIndex.around(-150,50,30),FeatureMode.ALL);assertEquals(1,visible.size());assertEquals(0,visible.getFirst().partIndex());assertTrue(FeaturePresentation.persistentParts(index,f.dimension(),f.geometry().bounds(),FeatureMode.HOVER).isEmpty());}
 @Test void renderPathsIncludeHoleAndOuterButNeverConnectComponents(){var f=feature(multipart("multi")).view();var second=FeaturePresentation.paths(f,1);assertEquals(2,second.size());assertTrue(second.stream().allMatch(FeaturePresentation.DrawPath::closed));assertEquals(1,FeaturePresentation.paths(f,0).size());assertTrue(FeaturePresentation.paths(f,-1).isEmpty());assertTrue(FeaturePresentation.paths(f,2).isEmpty());var line=feature(FeatureModelTest.line("river",1)).view();assertFalse(FeaturePresentation.paths(line,-1).getFirst().closed());}
 @Test void sameFeatureOverlappingComponentsDoNotCreateFalsePriorityTie(){var part=new FeatureGeometry.Part(circle(8,0,0,10),List.of());var g=FeatureGeometry.multipolygon(List.of(part,part));var selected=new FeatureIndex(List.of(view("one",g))).hover(FeatureModelTest.DIM,0,0,5);assertFalse(selected.ambiguous());assertEquals(0,selected.partIndex());}
 @Test void datelineStyleComponentsHaveNoCentralIndexHitOrConnectingPath(){var a=new FeatureGeometry.Part(circle(8,-12250,0,10),List.of());var b=new FeatureGeometry.Part(circle(8,12250,0,10),List.of());var f=view("seam",FeatureGeometry.multipolygon(List.of(a,b)));var index=new FeatureIndex(List.of(f));assertTrue(index.queryParts(f.dimension(),FeatureIndex.around(0,0,100)).isEmpty());for(double x:List.of(-12250D,12250D))assertEquals("seam",index.hover(f.dimension(),x,0,5).feature().id());assertTrue(FeaturePresentation.paths(f,0).getFirst().points().stream().allMatch(p->p.x()<0));assertTrue(FeaturePresentation.paths(f,1).getFirst().points().stream().allMatch(p->p.x()>0));}
 @Test void supports128PartsAnd4096TotalVerticesWithoutWholeFeatureCandidateBox(){var g=large();assertEquals(128,g.parts().size());assertEquals(128,g.ringCount());assertEquals(4096,g.vertexCount());var index=new FeatureIndex(List.of(view("large",g)));assertEquals(1,index.hover(FeatureModelTest.DIM,0,0,1).candidates());assertTrue(index.queryParts(FeatureModelTest.DIM,FeatureIndex.around(50,0,1)).isEmpty());}
 @Test void supports128RingsIncluding127HolesAt4096Vertices(){var holes=new ArrayList<FeatureGeometry.Ring>();for(int i=0;i<127;i++)holes.add(circle(32,(i%12)*60-350,(i/12)*60-350,10));var g=FeatureGeometry.polygon(new FeatureGeometry.Part(circle(32,0,0,5000),holes));assertEquals(128,g.ringCount());assertEquals(127,g.holeCount());assertEquals(4096,g.vertexCount());assertFalse(g.contains(-350,-350));assertTrue(g.contains(2000,0));}
 @Test void geometryStatisticsSeparateSchemaTypesPartsAndHoles(){var data=FeatureModelTest.catalog(FeatureModelTest.line("old",1),polygon("new",OUTER,"["+HOLE+"]",2),multipart("multi"));String s=FeatureCatalog.complexity(data);assertTrue(s.contains("schema-v1=1"));assertTrue(s.contains("schema-v2=2"));assertTrue(s.contains("parts=3"));assertTrue(s.contains("holes=2"));assertTrue(s.contains("largest=multi/12"));}
}
